<template>
  <div
    class="ga-table-container"
    :class="{
      'is-auto-height': isAutoHeight,
      'is-without-pagination': !showPagination,
    }"
  >
    <ElTable ref="tableRef" v-loading="props.loading" v-bind="$attrs" class="ga-table" :style="tableStyle" :data="props.data"
      :height="tableHeight" :max-height="props.maxHeight" :row-key="props.rowKey" :border="props.border"
      :stripe="props.stripe" :size="props.size" :fit="props.fit" :show-header="props.showHeader"
      :highlight-current-row="props.highlightCurrentRow" :empty-text="props.emptyText"
      :element-loading-text="props.loadingText">

    <!-- 列前置内容 -->
    <slot name="column-prepend" />

    <!-- 自定义列内容 -->
    <ElTableColumn v-for="(column, index) in props.columns" :key="getColumnKey(column, index)"
      v-bind="getColumnProps(column)">
      <template v-if="column.slot && slots[column.slot]" #default="scope">
        <slot :name="column.slot" v-bind="scope" />
      </template>
    </ElTableColumn>

    <!-- 自定义表格内容 -->
    <slot />

    <!-- 插入至表格最后一行之后的内容 -->
    <template v-if="slots.append" #append>
      <slot name="append" />
    </template>

    <!-- 当数据为空时自定义的内容 -->
    <template #empty>
      <slot name="empty">
        <ElEmpty :description="props.emptyText" />
      </slot>
    </template>

    </ElTable>
    <ElPagination v-if="showPagination" class="ga-pagination" :current-page="paginationConfig.currentPage"
      :page-size="paginationConfig.pageSize" :page-sizes="paginationConfig.pageSizes" :size="paginationConfig.size"
      :background="paginationConfig.background" :layout="paginationConfig.layout" :total="paginationConfig.total"
      @size-change="handleSizeChange" @current-change="handleCurrentChange" />
  </div>
</template>

<script setup lang="ts" generic="Row extends GaTableRow = GaTableRow">
import {
  ElTable,
  ElTableColumn,
  ElEmpty,
  ElPagination,
  vLoading,
} from 'element-plus'
import type { TableInstance } from 'element-plus'
import { ref, computed, nextTick, useAttrs, useSlots, watch } from 'vue'
import type { Slots, StyleValue } from 'vue'

import { getColumnKey, getColumnProps } from './column'
import type { GaTableProps } from './props'
import type { GaTableRow } from '../types'

defineOptions({
  name: 'GaTable',
  inheritAttrs: false,
})

const props = withDefaults(defineProps<GaTableProps<Row>>(), {
  data: () => [],
  columns: () => [],
  border: true,
  stripe: true,
  fit: true,
  showHeader: true,
  highlightCurrentRow: false,
  emptyText: '暂无数据',
  loading: false,
  loadingText: '加载中...',
  pagination: undefined,
  autoHeight: false,
})

const showPagination = computed(() => props.pagination !== false)

const isAutoHeight = computed(
  () =>
    props.autoHeight
    && props.height === undefined
    && props.maxHeight === undefined,
)

const tableHeight = computed(() =>
  props.height ?? (isAutoHeight.value ? '100%' : undefined),
)

const attrs = useAttrs()
const tableStyle = computed<StyleValue | undefined>(() => {
  if (isAutoHeight.value || props.height !== undefined) return undefined

  return [
    { height: undefined },
    attrs.style as StyleValue,
  ]
})

const paginationConfig = computed(() => {
  const pagination =
    typeof props.pagination === 'object'
      ? props.pagination
      : {}

  return {
    currentPage: pagination.currentPage ?? 1,
    pageSize: pagination.pageSize ?? 10,
    pageSizes: pagination.pageSizes ?? [10, 20, 30, 40, 50],
    total: pagination.total ?? 100,
    size: pagination.size ?? 'default',
    background: pagination.background ?? true,
    layout:
      pagination.layout ?? 'total, sizes, prev, pager, next, jumper',
  }
})

const slots: Slots = useSlots()
const tableRef = ref<TableInstance>()

watch(isAutoHeight, async (isActive, wasActive) => {
  if (!wasActive || isActive || props.height !== undefined) return

  await nextTick()

  if (isAutoHeight.value || props.height !== undefined) return

  tableRef.value?.doLayout()
})



const emit = defineEmits<{
  'size-change': [pageSize: number]
  'current-change': [currentPage: number]
}>()

// 分页当前页变化
const handleCurrentChange = (val: number) => {
  emit('current-change', val)
}

// 分页大小变化
const handleSizeChange = (val: number) => {
  emit('size-change', val)
}

defineExpose({
  tableRef,
})
</script>

<style lang="scss">
@use "../style/index.scss";
</style>
